-- SQL script to add articles to CMS categories
-- Each leaf category will have 9 articles
-- All articles belong to tenant_id = 1
-- Author ID is assumed to be 1 (adjust if needed)

-- Common cover image URL for all articles
SET @cover_image = 'http://gips3.baidu.com/it/u=3886271102,3123389489&fm=3028&app=3028&f=JPEG&fmt=auto?w=1280&h=960';

-- Current timestamp for creation and update times
SET @now = NOW();

-- First, get the category IDs for reference
-- Note: In a real database, you would use the actual IDs instead of selecting them like this

-- Get parent category ID (Product)
SELECT @product_category_id := id FROM cms_category WHERE name = 'Product' AND tenant_id = 1 LIMIT 1;

-- Get leaf category IDs
SELECT @imagediff_category_id := id FROM cms_category WHERE name = 'ImageDiff' AND tenant_id = 1 LIMIT 1;
SELECT @freetools_category_id := id FROM cms_category WHERE name = 'Free tools' AND tenant_id = 1 LIMIT 1;
SELECT @affiliate_category_id := id FROM cms_category WHERE name = 'Affiliate' AND tenant_id = 1 LIMIT 1;
SELECT @blog_category_id := id FROM cms_category WHERE name = 'Blog' AND tenant_id = 1 LIMIT 1;
SELECT @casestudies_category_id := id FROM cms_category WHERE name = 'Case Studies' AND tenant_id = 1 LIMIT 1;
SELECT @changelog_category_id := id FROM cms_category WHERE name = 'Changelog' AND tenant_id = 1 LIMIT 1;

