-- Now create the relationships between articles and categories in the ArticleCategory table
-- For ImageDiff category articles
SELECT id, @imagediff_category_id, @now, 1 FROM cms_article 
WHERE slug LIKE 'imagediff%' AND tenant_id = 1;

-- For Free Tools category articles
SELECT id, @freetools_category_id, @now, 1 FROM cms_article 
WHERE (slug LIKE '%tool%' OR slug LIKE 'free-%') AND tenant_id = 1 AND slug NOT LIKE 'imagediff%';

-- For Affiliate category articles
SELECT id, @affiliate_category_id, @now, 1 FROM cms_article 
WHERE slug LIKE 'affiliate%' AND tenant_id = 1;

-- For Blog category articles
SELECT id, @blog_category_id, @now, 1 FROM cms_article 
WHERE (slug LIKE 'future-%' OR slug LIKE 'building-%' OR slug LIKE 'accessibility-%' OR 
      slug LIKE 'web-performance%' OR slug LIKE 'psychology-%' OR slug LIKE 'devops-%' OR
      slug LIKE 'design-systems%' OR slug LIKE 'ai-software%' OR slug LIKE 'cross-browser%') AND tenant_id = 1;

-- For Case Studies category articles
SELECT id, @casestudies_category_id, @now, 1 FROM cms_article 
WHERE slug LIKE '%-case-study' AND tenant_id = 1;

-- For Changelog category articles
SELECT id, @changelog_category_id, @now, 1 FROM cms_article 
WHERE (slug LIKE 'product-release%' OR slug LIKE '%-update-%' OR 
      slug LIKE '%-edition-%' OR slug LIKE 'api-v%' OR 
      slug LIKE '%-notice%' OR slug LIKE '%-feature') AND tenant_id = 1;

-- Create article statistics records for all articles
SELECT id, FLOOR(RAND() * 1000), FLOOR(RAND() * 800), FLOOR(RAND() * 100), FLOOR(RAND() * 10), FLOOR(RAND() * 50), FLOOR(RAND() * 30), FLOOR(RAND() * 20), FLOOR(RAND() * 300) + 60, RAND() * 100, @now, 1
FROM cms_article WHERE tenant_id = 1;

-- Create article metadata for all articles
SELECT 
  id, 
  title, 
  SUBSTRING(excerpt, 1, 160), 
  CONCAT(SUBSTRING_INDEX(slug, '-', 1), ', ', SUBSTRING_INDEX(slug, '-', 2), ', ', SUBSTRING_INDEX(slug, '-', -1)), 
  title, 
  SUBSTRING(excerpt, 1, 100),
  cover_image, 
  @now, 
  @now, 
  1
FROM cms_article WHERE tenant_id = 1; 